class Solution { bool canFinish(vector<int>& nums,vector<int>& changeIndices,int seconds){vector<int> last(nums.size(),-1);for(int time=0;time<seconds;++time)last[changeIndices[time]-1]=time;for(int time:last)if(time<0)return false;long long available=0;for(int time=0;time<seconds;++time){int index=changeIndices[time]-1;if(time==last[index]){if(available<nums[index])return false;available-=nums[index];}else ++available;}return true;}public:int earliestSecondToMarkIndices(vector<int>& nums,vector<int>& changeIndices){int left=1,right=changeIndices.size()+1;while(left<right){int middle=(left+right)/2;if(canFinish(nums,changeIndices,middle))right=middle;else left=middle+1;}return left==(int)changeIndices.size()+1?-1:left;} };
